26	class ScopeCorrector : public StmtExprMutator {
27	public:
28	  explicit ScopeCorrector() {}
29	
30	  PrimFunc Correct(PrimFunc func) {
31	    collector_ = std::make_unique<BufferUseCollector>();
32	    collector_->operator()(func->body);
33	
34	    collector_->BuildHandleAllocMapping(func->body);
35	
36	    InferCorrectScopes();
37	
38	    auto new_body = this->operator()(func->body);
39	
40	    PrimFuncNode *fptr = func.CopyOnWrite();
41	    fptr->body = new_body;
42	
43	    // PrintDebugInfo();
44	
45	    return func;
46	  }
47	
48	private:
49	  struct BufferUseInfo {
50	    bool used_in_cube = false;
51	    bool used_in_vector = false;
52	    std::set<int> gemm_positions;
53	    std::set<std::string> func_names;
54	    std::vector<const CallNode *> call_sites;
55	  };
56	
57	  struct BufferAllocationInfo {
58	    const AllocateNode *alloc_node = nullptr;
59	    const VarNode *handle_var = nullptr;
60	    std::string original_scope;
61	    std::string corrected_scope;
62	    bool is_data_bound = false;
63	    bool from_block_alloc = false;
64	  };
65	  struct AscendCopyPositionInfo {
66	    bool is_first_in_at_least_one = false;
67	    bool is_second_in_at_least_one = false;
68	    std::vector<std::pair<const VarNode *, const VarNode *>> first_second_pairs;
69	    std::vector<std::pair<const VarNode *, const VarNode *>> second_first_pairs;
70	  };
71	
72	  class BufferUseCollector : public StmtExprVisitor {
73	  public:
74	    std::unordered_map<const VarNode *, AscendCopyPositionInfo>
75	        ascend_copy_position_info;
76	    std::vector<std::pair<const VarNode *, const VarNode *>>
77	        ascend_copy_buffer_pairs_;
78	    std::unordered_map<const VarNode *, BufferUseInfo> buffer_use_info;
79	    std::unordered_map<const VarNode *, BufferAllocationInfo> alloc_info;
80	    std::unordered_map<const VarNode *, const AllocateNode *> handle_to_alloc;
81	
82	    static bool IsGEMMFunction(const std::string &func_name) {
83	      return IsGEMMInternal(ToLower(func_name));
84	    }
85	
86	    static bool IsVectorFunction(const std::string &func_name) {
87	      std::string lower_name = ToLower(func_name);
88	
89	      if (IsGEMMInternal(lower_name))
90	        return false;
91	
92	      static const std::vector<std::string> kVectorKeywords = {"copy", "memcpy",
93	                                                               "dma"};
94	      return !ContainsAny(lower_name, kVectorKeywords);
95	    }
96	
97	    static std::string GetPtrStorageScope(Var buffer_var) {
98	      if (auto *ptr_type = buffer_var->type_annotation.as<PointerTypeNode>()) {
99	        return ptr_type->storage_scope;
100	      }
101	      return "";
102	    }
103	
104	    void BuildHandleAllocMapping(const Stmt &stmt) {
105	      class MappingBuilder : public StmtExprVisitor {
106	      public:
107	        MappingBuilder(BufferUseCollector *parent) : parent_(parent) {}
108	
109	        void VisitStmt_(const BlockNode *op) override {
110	          for (const Buffer &buffer : op->alloc_buffers) {
111	            const VarNode *handle_var = buffer->data.get();
112	
113	            BufferAllocationInfo info;
114	            info.alloc_node = nullptr;
115	            info.handle_var = handle_var;
116	            info.original_scope =
117	                BufferUseCollector::GetPtrStorageScope(buffer->data);
118	            info.is_data_bound = false;
119	            info.from_block_alloc = true;
120	
121	            parent_->alloc_info[handle_var] = info;
122	            parent_->handle_to_alloc[handle_var] = nullptr;
123	          }
124	
125	          StmtExprVisitor::VisitStmt_(op);
126	        }
127	
128	        void VisitStmt_(const AllocateNode *op) override {
129	
130	          const VarNode *handle_var = op->buffer_var.get();
131	
132	          BufferAllocationInfo info;
133	          info.alloc_node = op;
134	          info.handle_var = handle_var;
135	          info.original_scope =
136	              BufferUseCollector::GetPtrStorageScope(op->buffer_var);
137	          info.is_data_bound = false;
138	          info.from_block_alloc = false;
139	
140	          parent_->alloc_info[handle_var] = info;
141	          parent_->handle_to_alloc[handle_var] = op;
142	
143	          StmtExprVisitor::VisitStmt_(op);
144	        }
145	
146	      private:
147	        BufferUseCollector *parent_;
148	      };
149	
150	      MappingBuilder builder(this);
151	      builder.operator()(stmt);
152	    }
153	
154	    void VisitStmt_(const AllocateNode *op) override {
155	
156	      if (alloc_info.find(op->buffer_var.get()) == alloc_info.end()) {
157	        std::string scope = op->buffer_var->type_annotation.defined()
158	                                ? GetPtrStorageScope(op->buffer_var)
159	                                : "";
160	
161	        BufferAllocationInfo info;
162	        info.alloc_node = op;
163	        info.handle_var = op->buffer_var.get();
164	        info.original_scope = scope;
165	        info.is_data_bound = false;
166	        info.from_block_alloc = false;
167	        alloc_info[op->buffer_var.get()] = info;
168	        handle_to_alloc[op->buffer_var.get()] = op;
169	      }
170	
171	      StmtExprVisitor::VisitStmt_(op);
172	    }
173	
174	    void VisitStmt_(const BlockNode *op) override {
175	
176	      for (const Buffer &buffer : op->alloc_buffers) {
177	        const VarNode *handle_var = buffer->data.get();
178	
179	        if (alloc_info.find(handle_var) == alloc_info.end()) {
180	          std::string scope = buffer->data->type_annotation.defined()
181	                                  ? GetPtrStorageScope(buffer->data)
182	                                  : "";
183	
184	          BufferAllocationInfo info;
185	          info.alloc_node = nullptr;
186	          info.handle_var = handle_var;
187	          info.original_scope = scope;
188	          info.is_data_bound = false;
189	          info.from_block_alloc = true;
190	          alloc_info[handle_var] = info;
191	          handle_to_alloc[handle_var] = nullptr;
192	        }
193	      }
194	
195	      StmtExprVisitor::VisitStmt_(op);
196	    }
197	
198	    void VisitExpr_(const CallNode *op) override {
199	      std::string op_name = "";
200	      if (const OpNode *tl_op = op->op.as<OpNode>()) {
201	        op_name = tl_op->name;
202	        if (tl_op->name == "tl.ascend_copy") {
203	
204	          if (op->args.size() < 2) {
205	            return;
206	          }
207	
208	          const VarNode *first_buf_handle = nullptr;
209	          const CallNode *first_region = op->args[0].as<CallNode>();
210	          if (first_region && !first_region->args.empty() &&
211	              first_region->args[0].as<BufferLoadNode>()) {
212	            const BufferLoadNode *first_buf_load =
213	                first_region->args[0].as<BufferLoadNode>();
214	            first_buf_handle = first_buf_load->buffer->data.get();
215	          }
216	
217	          const VarNode *second_buf_handle = nullptr;
218	          const CallNode *second_region = op->args[1].as<CallNode>();
219	          if (second_region && !second_region->args.empty() &&
220	              second_region->args[0].as<BufferLoadNode>()) {
221	            const BufferLoadNode *second_buf_load =
222	                second_region->args[0].as<BufferLoadNode>();
223	            second_buf_handle = second_buf_load->buffer->data.get();
224	          }
225	
226	          if (first_buf_handle && second_buf_handle) {
227	            std::string first_name = first_buf_handle->name_hint;
228	            std::string second_name = second_buf_handle->name_hint;
229	            ascend_copy_buffer_pairs_.emplace_back(first_buf_handle,
230	                                                   second_buf_handle);
231	            AscendCopyPositionInfo &first_info =
232	                ascend_copy_position_info[first_buf_handle];
233	            AscendCopyPositionInfo &second_info =
234	                ascend_copy_position_info[second_buf_handle];
235	
236	            first_info.is_first_in_at_least_one = true;
237	            first_info.first_second_pairs.emplace_back(first_buf_handle,
238	                                                       second_buf_handle);
239	
240	            second_info.is_second_in_at_least_one = true;
241	            second_info.second_first_pairs.emplace_back(second_buf_handle,
242	                                                        first_buf_handle);
243	          }
244	
245	          if (first_buf_handle) {
246	            BufferUseInfo &info = buffer_use_info[first_buf_handle];
247	            info.func_names.insert("tl.ascend_copy");
248	            info.call_sites.push_back(op);
249	          }
250	
251	          if (second_buf_handle) {
252	            BufferUseInfo &info = buffer_use_info[second_buf_handle];
253	            info.func_names.insert("tl.ascend_copy");
254	            info.call_sites.push_back(op);
255	          }
256	        }
257	      }
258	
259	      if (op->op.same_as(builtin::call_extern())) {
260	        if (op->args.size() > 0) {
261	          if (auto *func_name = op->args[0].as<StringImmNode>()) {
262	            std::string name = func_name->value;
263	
264	            for (size_t i = 1; i < op->args.size(); ++i) {
265	              AnalyzeBufferInCall(op, i, name);
266	            }
267	          }
268	        }
269	      } else {
270	        if (!op_name.empty()) {
271	          for (size_t i = 0; i < op->args.size(); ++i) {
272	            AnalyzeBufferInCall(op, i, op_name);
273	          }
274	        }
275	      }
276	      StmtExprVisitor::VisitExpr_(op);
277	    }
278	
279	    void AnalyzeBufferInCall(const CallNode *call, size_t arg_idx,
280	                             const std::string &func_name) {
281	      auto *arg = call->args[arg_idx].as<CallNode>();
282	      if (!arg || !arg->op.same_as(builtin::tvm_access_ptr())) {
283	        return;
284	      }
285	
286	      if (arg->args.size() > 1) {
287	        if (auto *var = arg->args[1].as<VarNode>()) {
288	
289	          BufferUseInfo &info = buffer_use_info[var];
290	          info.func_names.insert(func_name);
291	          info.call_sites.push_back(call);
292	
293	          if (IsGEMMFunction(func_name)) {
294	            info.used_in_cube = true;
295	
296	            int gemm_position = DetermineGEMMPosition(call, arg_idx, func_name);
297	            if (gemm_position >= 0) {
298	              info.gemm_positions.insert(gemm_position);
299	            }
300	          }
301	
302	          if (IsVectorFunction(func_name)) {
303	            info.used_in_vector = true;
304	          }
305	        }
306	      }
307	    }
308	
309	    int DetermineGEMMPosition(const CallNode *call, size_t arg_idx,
310	                              const std::string &func_name) {
311	      int access_ptr_count = 0;
312	      for (size_t i = 1; i < arg_idx; ++i) {
313	        if (auto *prev_arg = call->args[i].as<CallNode>()) {
314	          if (prev_arg->op.same_as(builtin::tvm_access_ptr())) {
315	            access_ptr_count++;
316	          }
317	        }
318	      }
319	      if (func_name.find("gemm") != std::string::npos ||
320	          func_name.find("mma") != std::string::npos) {
321	        if (access_ptr_count == 0)
322	          return 0; // A -> L0A
323	        if (access_ptr_count == 1)
324	          return 1; // B -> L0B
325	        if (access_ptr_count == 2)
326	          return 2; // C -> L0C
327	      }
328	
329	      return -1;
330	    }
331	
332	    const AllocateNode *GetAllocForHandle(const VarNode *handle) const {
333	      auto it = handle_to_alloc.find(handle);
334	      return it != handle_to_alloc.end() ? it->second : nullptr;
335	    }
336	
337	    BufferAllocationInfo *GetAllocInfo(const VarNode *handle) {
338	      auto it = alloc_info.find(handle);
339	      return it != alloc_info.end() ? &it->second : nullptr;
340	    }
341	
342	    BufferUseInfo *GetUseInfo(const VarNode *handle) {
343	      auto it = buffer_use_info.find(handle);
344	      return it != buffer_use_info.end() ? &it->second : nullptr;
345	    }
