347	  private:
348	    static std::string ToLower(std::string_view str) {
349	      std::string lower_str(str);
350	      std::transform(lower_str.begin(), lower_str.end(), lower_str.begin(),
351	                     [](unsigned char c) { return std::tolower(c); });
352	      return lower_str;
353	    }
354	
355	    static bool ContainsAny(const std::string &str,
356	                            const std::vector<std::string> &keywords) {
357	      for (const auto &keyword : keywords) {
358	        if (str.find(keyword) != std::string::npos) {
359	          return true;
360	        }
361	      }
362	      return false;
363	    }
364	
365	    static bool IsGEMMInternal(const std::string &lower_name) {
366	      static const std::vector<std::string> kGemmKeywords = {"gemm", "mma",
367	                                                             "matmul"};
368	      return ContainsAny(lower_name, kGemmKeywords);
369	    }
370	  };
371	
372	  void InferCorrectScopes() {
373	    for (const auto &kv : collector_->alloc_info) {
374	      const VarNode *handle = kv.first;
375	      BufferAllocationInfo *alloc_info = collector_->GetAllocInfo(handle);
376	      if (!alloc_info)
377	        continue;
378	
379	      BufferUseInfo *use_info = collector_->GetUseInfo(handle);
380	
381	      std::string original_scope = alloc_info->original_scope;
382	      std::string corrected_scope = original_scope;
383	
384	      if (original_scope == "local.fragment") {
385	        if (use_info && !use_info->gemm_positions.empty()) {
386	          if (use_info->gemm_positions.count(0) > 0) {
387	            corrected_scope = "wmma.matrix_a"; // L0A
388	          } else if (use_info->gemm_positions.count(1) > 0) {
389	            corrected_scope = "wmma.matrix_b"; // L0B
390	          } else if (use_info->gemm_positions.count(2) > 0) {
391	            corrected_scope = "wmma.accumulator"; // L0C
392	          } else {
393	            corrected_scope = "wmma.accumulator";
394	          }
395	        } else {
396	          corrected_scope = "wmma.accumulator";
397	        }
398	      } else if (original_scope == "shared") {
399	        if (use_info) {
400	          bool only_in_ascend_copy = false;
401	          if (use_info->used_in_vector && !use_info->used_in_cube) {
402	            corrected_scope = "shared.ub";
403	          } else if (use_info->used_in_cube && !use_info->used_in_vector) {
404	            corrected_scope = "shared.l1";
405	          } else if (use_info->used_in_cube && use_info->used_in_vector) {
406	            bool has_conflict = CheckSharedBufferConflict(use_info);
407	            if (has_conflict) {
408	              // todo
409	            }
410	            corrected_scope = "shared.l1";
411	          } else {
412	            corrected_scope = original_scope;
413	          }
414	        } else {
415	          corrected_scope = original_scope;
416	        }
417	      } else if (original_scope == "shared.l1") {
418	        corrected_scope = "shared.l1";
419	      }
420	
421	      alloc_info->corrected_scope = corrected_scope;
422	
423	      if (corrected_scope != original_scope) {
424	        alloc_info->corrected_scope = corrected_scope;
425	
426	        if (alloc_info->alloc_node) {
427	          scope_corrections_[alloc_info->alloc_node] = corrected_scope;
428	        }
429	
430	        handle_scope_corrections_[handle] = corrected_scope;
431	      } else if (original_scope == "shared.l1") {
432	        // Even though the scope is unchanged (shared.l1 -> shared.l1),
433	        // force a Var replacement. This replicates the original behavior
434	        // where shared.l1 was always rewritten to a different scope string
435	        // (previously a different scope string), triggering Var
436	        // recreation causes InjectDefaultLayoutMap to re-evaluate the default
437	        // layout for the new Var, which is essential for layout annotation
438	        // consistency (e.g., splice patterns where the default zN layout
439	        // must be (re)injected for the rewritten buffer handle).
440	        if (alloc_info->alloc_node) {
441	          scope_corrections_[alloc_info->alloc_node] = corrected_scope;
442	        }
443	        handle_scope_corrections_[handle] = corrected_scope;
444	      }
445	
446	      for (const auto &kv : collector_->alloc_info) {
447	        const VarNode *handle = kv.first;
448	        BufferAllocationInfo *alloc_info = collector_->GetAllocInfo(handle);
449	        if (!alloc_info || alloc_info->original_scope != "shared") {
450	          continue;
451	        }
452	
453	        BufferUseInfo *use_info = collector_->GetUseInfo(handle);
454	        if (!use_info) {
455	          continue;
456	        }
457	
458	        bool only_in_ascend_copy = false;
459	        if (!use_info->used_in_cube) {
460	          bool only_valid_funcs = true;
461	          for (const auto &func_name : use_info->func_names) {
462	            if (func_name != "tl.ascend_copy" &&
463	                func_name != "tl.ascend_dump_tensor") {
464	              only_valid_funcs = false;
465	              break;
466	            }
467	          }
468	          if (only_valid_funcs) {
469	            only_in_ascend_copy = true;
470	          }
471	        }
472	
473	        if (!only_in_ascend_copy) {
474	          continue;
475	        }
476	        auto pos_info_it = collector_->ascend_copy_position_info.find(handle);
477	        if (pos_info_it == collector_->ascend_copy_position_info.end()) {
478	          continue;
479	        }
480	
481	        const AscendCopyPositionInfo &pos_info = pos_info_it->second;
482	
483	        bool found_qualified_copy = false;
484	
485	        for (const auto &pair : pos_info.first_second_pairs) {
486	          const VarNode *second_handle = pair.second;
487	          BufferAllocationInfo *second_alloc =
488	              collector_->GetAllocInfo(second_handle);
489	          if (!second_alloc) {
490	            continue;
491	          }
492	
493	          std::string second_scope = second_alloc->corrected_scope;
494	          if (second_scope.empty()) {
495	            second_scope = second_alloc->original_scope;
496	          }
497	
498	          if (second_scope == "wmma.matrix_a" ||
499	              second_scope == "wmma.matrix_b") {
500	            found_qualified_copy = true;
501	            break;
502	          }
503	        }
504	        if (found_qualified_copy) {
505	          alloc_info->corrected_scope = "shared.l1";
506	        } else {
507	          alloc_info->corrected_scope = "shared.ub";
508	        }
509	
510	        bool has_dump_tensor = false;
511	        if (use_info) {
512	          for (const auto &func : use_info->func_names) {
513	            if (func == "tl.ascend_dump_tensor" || func == "tl.dump_tensor") {
514	              has_dump_tensor = true;
515	              break;
516	            }
517	          }
518	        }
519	
520	        bool should_apply = false;
521	        if (has_dump_tensor && alloc_info->corrected_scope == "shared.l1") {
522	          should_apply = true;
523	        } else if (alloc_info->corrected_scope != alloc_info->original_scope) {
524	          should_apply = true;
525	        }
526	
527	        if (should_apply) {
528	          if (alloc_info->alloc_node) {
529	            scope_corrections_[alloc_info->alloc_node] =
530	                alloc_info->corrected_scope;
531	          }
532	          handle_scope_corrections_[handle] = alloc_info->corrected_scope;
533	        }
534	      }
535	    }
536	    const std::string UB_SCOPE = "shared.ub";
537	
538	    for (const auto &buf_pair : collector_->ascend_copy_buffer_pairs_) {
539	      const VarNode *first_buf_handle = buf_pair.first;
540	      const VarNode *second_buf_handle = buf_pair.second;
541	
542	      BufferAllocationInfo *first_alloc_info =
543	          collector_->GetAllocInfo(first_buf_handle);
544	      BufferAllocationInfo *second_alloc_info =
545	          collector_->GetAllocInfo(second_buf_handle);
546	      if (!first_alloc_info || !second_alloc_info) {
547	        continue;
548	      }
549	
550	      std::string first_buf_scope = first_alloc_info->corrected_scope.empty()
551	                                        ? first_alloc_info->original_scope
552	                                        : first_alloc_info->corrected_scope;
553	      bool first_is_ub = (first_buf_scope == UB_SCOPE);
554	      std::string first_name = first_buf_handle->name_hint;
555	      std::string second_name = second_buf_handle->name_hint;
556	
557	      if (!first_is_ub) {
558	        continue;
559	      }
560	
561	      BufferUseInfo *second_use_info =
562	          collector_->GetUseInfo(second_buf_handle);
563	      bool second_no_cube_vector = false;
564	      if (second_use_info == nullptr) {
565	        second_no_cube_vector = true;
566	      } else {
567	        if (!second_use_info->used_in_cube &&
568	            !second_use_info->used_in_vector) {
569	          second_no_cube_vector = true;
570	        }
571	      }
572	
573	      if (!second_no_cube_vector) {
574	        continue;
575	      }
576	
577	      std::string second_old_scope = second_alloc_info->corrected_scope.empty()
578	                                         ? second_alloc_info->original_scope
579	                                         : second_alloc_info->corrected_scope;
580	
581	      if (second_alloc_info->original_scope == "shared.l1") {
582	        continue;
583	      }
584	
585	      second_alloc_info->corrected_scope = UB_SCOPE;
586	      handle_scope_corrections_[second_buf_handle] = UB_SCOPE;
587	      if (second_alloc_info->alloc_node) {
588	        scope_corrections_[second_alloc_info->alloc_node] = UB_SCOPE;
589	      }
590	    }
591	  }
