593	  bool CheckSharedBufferConflict(const BufferUseInfo *use_info) {
594	    return false;
595	  }
596	
597	  void PrintDebugInfo() {
598	    LOG(INFO) << "=== Scope Correction Results ===";
599	    for (const auto &kv : collector_->alloc_info) {
600	      const VarNode *handle = kv.first;
601	      const BufferAllocationInfo &info = kv.second;
602	
603	      BufferUseInfo *use_info = collector_->GetUseInfo(handle);
604	
605	      LOG(INFO) << "Buffer: " << handle->name_hint;
606	      LOG(INFO) << "  Original scope: " << info.original_scope;
607	      LOG(INFO) << "  Corrected scope: " << info.corrected_scope;
608	
609	      if (use_info) {
610	        if (!use_info->func_names.empty()) {
611	          LOG(INFO) << "  Used in functions:";
612	          for (const auto &func : use_info->func_names) {
613	            LOG(INFO) << "    - " << func;
614	          }
615	        }
616	
617	        if (!use_info->gemm_positions.empty()) {
618	          LOG(INFO) << "  GEMM positions:";
619	          for (int pos : use_info->gemm_positions) {
620	            const char *role = "Unknown";
621	            if (pos == 0)
622	              role = "A (L0A)";
623	            else if (pos == 1)
624	              role = "B (L0B)";
625	            else if (pos == 2)
626	              role = "C (L0C)";
627	            LOG(INFO) << "    - Position " << pos << ": " << role;
628	          }
629	        }
630	
631	        LOG(INFO) << "  Used in Cube: " << use_info->used_in_cube;
632	        LOG(INFO) << "  Used in Vector: " << use_info->used_in_vector;
633	      }
634	      LOG(INFO) << "---";
635	    }
636	  }
637	
638	  std::unordered_map<const AllocateNode *, std::string> scope_corrections_;
639	  std::unordered_map<const VarNode *, std::string> handle_scope_corrections_;
640	  std::unordered_map<const VarNode *, Var> var_replacements_;
641	  std::unique_ptr<BufferUseCollector> collector_;
642	  std::unordered_map<const VarNode *, Buffer> buffer_replacements_;
643	
644	  static std::string GetPtrStorageScope(Var buffer_var) {
645	    if (auto *ptr_type = buffer_var->type_annotation.as<PointerTypeNode>()) {
646	      return ptr_type->storage_scope;
647	    }
648	    return "";
649	  }
650	
651	  Var CreateVarWithCorrectScope(const Var &old_var,
652	                                const std::string &new_scope) {
653	    auto it = var_replacements_.find(old_var.get());
654	    if (it != var_replacements_.end()) {
655	      return it->second;
656	    }
657	
658	    auto ptr_type = old_var->type_annotation.as<PointerTypeNode>();
659	    if (ptr_type) {
660	      auto new_ptr_type = PointerType(ptr_type->element_type, new_scope);
661	      Var new_var(old_var->name_hint, new_ptr_type);
662	      var_replacements_[old_var.get()] = new_var;
663	      return new_var;
664	    }
665	
666	    auto new_ptr_type = PointerType(PrimType(DataType::Void()), new_scope);
667	    Var new_var(old_var->name_hint, new_ptr_type);
668	    var_replacements_[old_var.get()] = new_var;
669	    return new_var;
670	  }
671	
672	  bool TryGetRewrittenBuffer(const Buffer &old_buffer, Buffer *new_buffer) {
673	    const auto *key = old_buffer->data.get();
674	
675	    // Check whether this buffer's data Var needs a scope correction.
676	    auto scope_it = handle_scope_corrections_.find(key);
677	    if (scope_it == handle_scope_corrections_.end())
678	      return false;
679	
680	    // If we already created a replacement Buffer for this Var, reuse it.
681	    auto repl_it = buffer_replacements_.find(key);
682	    if (repl_it != buffer_replacements_.end()) {
683	      *new_buffer = repl_it->second;
684	      return true;
685	    }
686	
687	    // Construct the new buffer
688	    Var new_data =
689	        CreateVarWithCorrectScope(old_buffer->data, scope_it->second);
690	    *new_buffer = Buffer(new_data, old_buffer->dtype, old_buffer->shape,
691	                         old_buffer->strides, old_buffer->elem_offset,
692	                         old_buffer->name, old_buffer->data_alignment,
693	                         old_buffer->offset_factor, old_buffer->buffer_type);
694	    return true;
695	  }
696	
697	  Stmt VisitStmt_(const AllocateNode *op) override {
698	    auto it = scope_corrections_.find(op);
699	    if (it != scope_corrections_.end()) {
700	      std::string new_scope = it->second;
701	
702	      Var new_buffer_var = op->buffer_var;
703	      auto handle_it = handle_scope_corrections_.find(op->buffer_var.get());
704	      if (handle_it != handle_scope_corrections_.end()) {
705	        new_buffer_var =
706	            CreateVarWithCorrectScope(op->buffer_var, handle_it->second);
707	      }
708	
709	      return Allocate(new_buffer_var, op->dtype, op->extents, op->condition,
710	                      VisitStmt(op->body));
711	    }
712	
713	    return StmtExprMutator::VisitStmt_(op);
714	  }
715	
716	  Stmt VisitStmt_(const BlockNode *op) override {
717	    Array<Buffer> new_alloc_buffers;
718	
719	    for (const Buffer &buffer : op->alloc_buffers) {
720	      const VarNode *handle = buffer->data.get();
721	      auto it = handle_scope_corrections_.find(handle);
722	
723	      if (it != handle_scope_corrections_.end()) {
724	        std::string new_scope = it->second;
725	
726	        Var new_data = CreateVarWithCorrectScope(buffer->data, new_scope);
727	        var_replacements_[handle] = new_data;
728	
729	        auto new_buffer =
730	            Buffer(new_data, buffer->dtype, buffer->shape, buffer->strides,
731	                   buffer->elem_offset, buffer->name, buffer->data_alignment,
732	                   buffer->offset_factor, buffer->buffer_type);
733	
734	        new_alloc_buffers.push_back(new_buffer);
735	        buffer_replacements_[handle] = new_buffer;
736	      } else {
737	        new_alloc_buffers.push_back(buffer);
738	      }
739	    }
740	
741	    // Inject default physical layout for L1 Buffer
742	    Map<String, ObjectRef> new_annotations =
743	        InjectDefaultLayoutMap(new_alloc_buffers, op->annotations);
744	
745	    auto new_body = VisitStmt(op->body);
746	    auto new_block =
747	        Block(op->iter_vars, op->reads, op->writes, op->name_hint, new_body,
748	              op->init, new_alloc_buffers, op->match_buffers, new_annotations);
749	
750	    return new_block;
751	  }
752	
753	  /*!
754	   * \brief Ensure all L1-level (shared.l1) Buffers have physical memory layout
755	   * descriptions.
756	   *
757	   * \note
758	   * If the frontend user does not explicitly declare a layout via
759	   * T.annotate_layout, the backend will not be able to compute correct 1D
760	   * physical address offsets during LowerTileOp. Therefore, the compiler must
761	   * perform defensive fallback here to inject default zN Layout for L1 Buffers
762	   * missing a Layout.
763	   */
764	  Map<String, ObjectRef>
765	  InjectDefaultLayoutMap(const Array<Buffer> &alloc_buffers,
766	                         Map<String, ObjectRef> annotations) {
767	    Map<Var, tl::Layout> layout_map;
768	
769	    // Extract existing layout_map, respecting user's explicit definitions
770	    if (annotations.count(tl::attr::kLayoutMap)) {
771	      layout_map =
772	          Downcast<Map<Var, tl::Layout>>(annotations.Get(tl::attr::kLayoutMap));
773	    }
774	
775	    bool layout_map_changed = false;
776	
777	    for (const Buffer &buf : alloc_buffers) {
778	      std::string scope = "";
779	      if (auto *ptr_type = buf->data->type_annotation.as<PointerTypeNode>()) {
780	        scope = ptr_type->storage_scope;
781	      }
782	
783	      // Only data entering L1 Buffer needs to participate in Cube operations
784	      // and requires fractal layout transformation.
785	      if (scope == "shared.l1") {
786	        // Avoid overwriting user-defined layouts (e.g., user intentionally
787	        // specified nZ instead of zN).
788	        if (layout_map.count(buf->data) == 0) {
789	          tl::Layout default_zn_layout = CreateDefaultZnLayout(buf);
790	          layout_map.Set(buf->data, default_zn_layout);
791	          layout_map_changed = true;
792	        }
793	      }
794	    }
795	
796	    // Only update Annotations node when actual modifications occur, avoiding
797	    // unnecessary IR copy overhead
798	    if (layout_map_changed) {
799	      annotations.Set(tl::attr::kLayoutMap, layout_map);
800	    }
801	
802	    return annotations;
803	  }
804	
805	  tl::Layout CreateDefaultZnLayout(const Buffer &buf) {
806	    // The affine transformation logic for layout is well-implemented and easy
807	    // to debug on the Python side (make_zn_layout). Dynamically callback Python
808	    // logic via FFI to avoid hardcoding complex AST expression trees in C++.
809	    const tvm::runtime::PackedFunc *make_zn_func =
810	        tvm::runtime::Registry::Get("tl.ascend.make_zn_layout");
811	
812	    ICHECK(make_zn_func != nullptr)
813	        << "Cannot find global function 'tl.ascend.make_zn_layout'. "
814	        << "Please make sure it is registered in Python.";
815	
816	    tvm::runtime::TVMRetValue ret = (*make_zn_func)(buf);
817	    return ret.operator tl::Layout();
818	  }
819	
820	  PrimExpr VisitExpr_(const VarNode *op) override {
821	    auto it = handle_scope_corrections_.find(op);
822	    if (it != handle_scope_corrections_.end()) {
823	      Var old_var = GetRef<Var>(op);
824	
825	      auto var_it = var_replacements_.find(op);
826	      if (var_it != var_replacements_.end()) {
827	        return var_it->second;
828	      }
829	
830	      Var new_var = CreateVarWithCorrectScope(old_var, it->second);
831	      var_replacements_[op] = new_var;
832	      return std::move(new_var);
833	    }
834	
835	    return GetRef<PrimExpr>(op);
836	  }
837	
838	  PrimExpr VisitExpr_(const BufferLoadNode *op) override {
839	    Buffer new_buffer;
840	    if (!TryGetRewrittenBuffer(op->buffer, &new_buffer)) {
841	      return StmtExprMutator::VisitExpr_(op);
842	    }
843	
844	    Array<PrimExpr> indices;
845	    indices.reserve(op->indices.size());
846	    for (const auto &index : op->indices) {
847	      indices.push_back(VisitExpr(index));
848	    }
849	
850	    return BufferLoad(new_buffer, indices);
851	  }
852	
853	  Stmt VisitStmt_(const BufferStoreNode *op) override {
854	    Buffer new_buffer;
855	    if (!TryGetRewrittenBuffer(op->buffer, &new_buffer)) {
856	      return StmtExprMutator::VisitStmt_(op);
857	    }
858	
859	    PrimExpr value = VisitExpr(op->value);
860	
861	    Array<PrimExpr> indices;
862	    indices.reserve(op->indices.size());
863	    for (const PrimExpr &index : op->indices) {
864	      indices.push_back(VisitExpr(index));
865	    }
866	
867	    return BufferStore(new_buffer, value, indices);
868	  }
869	
870	  PrimExpr VisitExpr_(const CallNode *op) override {
871	    if (op->op.same_as(builtin::tvm_access_ptr())) {
872	
873	      if (op->args.size() > 1) {
874	        if (auto *var = op->args[1].as<VarNode>()) {
875	          auto it = handle_scope_corrections_.find(var);
876	          if (it != handle_scope_corrections_.end()) {
877	
878	            Array<PrimExpr> new_args;
879	            new_args.push_back(op->args[0]); // type annotation
880	            new_args.push_back(
881	                CreateVarWithCorrectScope(GetRef<Var>(var), it->second));
882	
883	            for (size_t i = 2; i < op->args.size(); ++i) {
884	              new_args.push_back(VisitExpr(op->args[i]));
885	            }
886	
887	            return Call(op->dtype, op->op, new_args, op->span);
888	          }
889	        }
890	      }
891	    }
892	
893	    return StmtExprMutator::VisitExpr_(op);
894	  }
895	};
896	
897	transform::Pass InferAllocScope() {
898	  auto pass_func = [](PrimFunc f, IRModule m, transform::PassContext ctx) {
899	    ScopeCorrector corrector;
900	    return corrector.Correct(std::move(f));
901	  };
902	  return transform::CreatePrimFuncPass(pass_func, 0, "tl.InferAllocScope", {});
903	}
904	
905	TVM_REGISTER_GLOBAL("tl.transform.InferAllocScope")
906	    .set_body_typed(InferAllocScope);
907	
908	} // namespace tir
909	} // namespace tvm
